function validate([hens, grains]) {
  if (!Array.isArray(hens) || hens.length < 1 || hens.length > 20000) return 'hens needs 1 to 20000 positions.';
  if (!Array.isArray(grains) || grains.length < 1 || grains.length > 20000) return 'grains needs 1 to 20000 positions.';
  const bad = v => !Number.isInteger(v) || v < 0 || v > 1e9;
  if (hens.some(bad) || grains.some(bad)) return 'Every position is an integer between 0 and 10^9.';
  return null;
}

