function minimumTime(hens, grains) {
  hens.sort((a, b) => a - b);
  grains.sort((a, b) => a - b);
  const canFinish = (time) => {
    let next = 0;
    for (const hen of hens) {
      if (next === grains.length) break;
      let reach = hen + time;
      if (grains[next] < hen) {
        const back = hen - grains[next];
        if (back > time) return false;
        reach = hen + Math.max(time - 2 * back, Math.floor((time - back) / 2));
      }
      while (next < grains.length && grains[next] <= reach) next++;
    }
    return next === grains.length;
  };
  let low = 0;
  let high = Math.abs(hens[0] - grains[0]) + grains[grains.length - 1] - grains[0];
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (canFinish(mid)) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

