function minimumTime(hens, grains) {
  // Try every way to hand the grains to the hens; a hen covering [lo, hi] needs a fixed, known time.
  const cover = (hen, lo, hi) => {
    if (hen <= lo) return hi - hen;
    if (hen >= hi) return hen - lo;
    return Math.min(2 * (hen - lo) + (hi - hen), (hen - lo) + 2 * (hi - hen));
  };
  const lo = hens.map(() => Infinity), hi = hens.map(() => -Infinity);
  let best = Infinity;
  const assign = (j) => {
    if (j === grains.length) {
      let worst = 0;
      for (let h = 0; h < hens.length; h++) if (lo[h] !== Infinity) worst = Math.max(worst, cover(hens[h], lo[h], hi[h]));
      best = Math.min(best, worst);
      return;
    }
    for (let h = 0; h < hens.length; h++) {
      const oldLo = lo[h], oldHi = hi[h];
      lo[h] = Math.min(oldLo, grains[j]);
      hi[h] = Math.max(oldHi, grains[j]);
      assign(j + 1);
      lo[h] = oldLo;
      hi[h] = oldHi;
    }
  };
  assign(0);
  return best;
}

