function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 4);
    const m = pick(1, 6);
    const span = rand() < 0.8 ? pick(0, 25) : 1000000000;
    return [Array.from({ length: n }, () => pick(0, span)), Array.from({ length: m }, () => pick(0, span))];
  }
  const mode = rand();
  if (mode < 0.4) {
    return [Array.from({ length: 2000 }, () => pick(0, 1000000000)), Array.from({ length: 2000 }, () => pick(0, 1000000000))];
  }
  if (mode < 0.7) {
    const n = pick(1, 15);
    return [Array.from({ length: n }, () => pick(0, 1000000000)), Array.from({ length: 2000 }, () => pick(0, 1000000000))];
  }
  const span = pick(1000, 20000);
  return [Array.from({ length: pick(200, 2000) }, () => pick(0, span)), Array.from({ length: 2000 }, () => pick(0, span))];
}
